VALUES (
  '153e8147-3cf9-5817-ac8e-f017a0347782', '45a14d06-f389-5034-8f83-b2e6d6d524a2',
  'Implement static method `selectionSort` in class `Sorting` to sort an array in ascending order. After each selection, we will print out a list to check (using `printArray`).

```cpp
#include <iostream>
using namespace std;

template <class T>
class Sorting
{
public:
    /* Function to print an array */
    static void printArray(T *start, T *end)
    {
        int size = end - start;
        for (int i = 0; i < size - 1; i++)
            cout << start[i] << ", ";
        cout << start[size - 1];
        cout << endl;
    }

    static void selectionSort(T *start, T *end);
};
```

**For example:**

| Test | Result |
| :--- | :--- |
| `int arr[] = {9, 2, 8, 1, 0, -2};` | `-2, 2, 8, 1, 0, 9` |
| `Sorting<int>::selectionSort(&arr[0], &arr[6]);` | `-2, 0, 8, 1, 2, 9` |
| | `-2, 0, 1, 8, 2, 9` |
| | `-2, 0, 1, 2, 8, 9` |
| | `-2, 0, 1, 2, 8, 9` |

Đáp án: ```cpp
template <class T>
void Sorting<T>::selectionSort(T *start, T *end)
{
    int i = 0;
    int min_idx = 0;
    // One by one move boundary of unsorted subarray
    for (i = 0; *(start+i) != *(end - 1); i++)
    {
        // Find the minimum element in unsorted array
        min_idx = i;
        for (int j = i+1; *(start+j) != *end; j++)
        {
            if (*(start+j) < *(start+ min_idx)) min_idx = j;
        }
        // Swap the found minimum element with the first element
        T temp = *(start+ min_idx);
        *(start+min_idx) = *(start+i);
        *(start+i) = temp;
        printArray(start,end);
        // swap(&arr[min_idx], &arr[i]);
    }
}

```', 1
);

