VALUES (
  '03133576-ce92-5766-88bf-a067256a7b55', '45a14d06-f389-5034-8f83-b2e6d6d524a2',
  'Two strings are called permutation of each other when they have exactly the same number of character, and the number of appearance of each character in each string must be the same.

For example:

String a = "abba" and String b = "baba" are said to be permutation of each other. While String a = "abbc" and String b = "baba" are not.

Your task in this exercise is to implement the `isPermutation` function. Note that, you can write one or more functions in order to achieve this exercise.

```cpp
#ifndef SORTINGAPPLICATION_H
#define SORTINGAPPLICATION_H
#include <iostream>
#include <string>
using namespace std;
bool isPermutation (string a, string b) {}
#endif /* SORTINGAPPLICATION_H */
```

For example:

| Test | Result |
| :--- | :--- |
| `string a = "abba";`<br>`string b="baba";`<br>`cout << isPermutation(a, b);` | 1 |
| `string a = "abbac";`<br>`string b="baba";`<br>`cout << isPermutation(a, b);` | 0 |

Đáp án: ```cpp
bool isPermutation (string a, string b) {
    int arr[26];
    int brr[26];
    for (int i = 0; i < 26; ++i) arr[i] = 0;
    for (int i = 0; i < 26; ++i) brr[i] = 0;

    for (int i = 0; i < (int)a.size() ; ++i) ++arr[a[i]-97];
    for (int i = 0; i < (int)b.size() ; ++i) ++brr[b[i]-97];

    for (int i = 0; i < 26; ++i)
    {
        if (arr[i] != brr[i]) return false;
    }
    return true;
}
```', 5
);

INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  '61494500-e62c-5de4-a4a3-86b3574adfd6', '45a14d06-f389-5034-8f83-b2e6d6d524a2',
  'Ann has gone to New York City for 1 week. Ann is friendly and helpful person so she decided to visit all her neighbor in this city. But she can not remember that she has visited some neighbors before or not. Therefore, she may visit one neighbor many times. Find the neighbor she has visited the most? If there are many results, return result which followed by alphabet.

You have to implement `majorityNeighbor(vector<string>& neighbor)` to return the neighbor that Ann has visited the most.

Example: `[Peter, Bob, Andrew, Peter, Bob, Peter, Bob, Peter]` → Peter

Note that: we included iostream, vector, list, string so that you don''t need to include them again.

Constraints:
1. `1 <= neighbor <= 1000`
2. `neighbor[i]` is a string that contains letter only.

For example:

| Test | Result |
| :--- | :--- |
| `vector<string> nums = { "Peter", "Bob", "Andrew", "Peter", "Bob", "Peter", "Bob", "Peter" };`<br>`Neighbor s;`<br>`cout << s.majorityNeighbor(nums);` | Peter |

Đáp án: ```cpp
class Neighbor {
public:
    string majorityNeighbor(vector<string>& neighbor) {
        int size = neighbor.size();
        vector<string> diff;
        for (int i = 0; i < size; ++i)
        {
            if (i == 0) {diff.push_back(neighbor[i]); continue;}
            for (int j = i-1; j >= 0; --j)
            {
                if (neighbor[j] == neighbor[i]) break;
                else
                {
                    if (j == 0) diff.push_back(neighbor[i]);
                }
            }
        }
        vector<int> app((int)diff.size());
        for (int i = 0; i < (int)app.size(); ++i)
        {
            app[i] = 0;
        }
        for (int j = 0; j < size; ++j)
        {
            for (int h = 0; h < (int)diff.size(); ++h)
            {
                if (diff[h] == neighbor[j]) ++app[h];
            }
        }
        int max_pos = 0;
        int max = app[0];
        for (int j = 1; j < (int)app.size(); ++j)
        {
            if (max < app[j])
            {
                max = app[j];
                max_pos = j;
            }
        }
        string res = diff[max_pos];
        string curr = "";
        
        for (int j = max_pos+1; j < (int)app.size(); ++j)
        {
            if (max == app[j])
            {
                curr = diff[j];
                if (res > curr ) res = curr;
            }
        }
        return res;
    }
};
```', 6
);

